class Main {
    static class Box {
        // 객체마다 따로 생기는 칸이에요.
        int value;
    }

    public static void main(String[] args) {
        // 이번 실험의 시작값이에요.
        int n = 3;
        Box a = new Box();
        Box b = new Box();
        // 두 객체가 각자 값을 가져요.
        a.value = n;
        b.value = n;
        // 바꿀 대상 객체를 확인해요.
        b.value = n + 2;
        System.out.println(a.value + " " + b.value);
    }
}
